// Page 11 VC direction control and helper decode slice.
//
// Captures the visually checked L121A/K129/L122B/L124A/L128A chain that
// drives the shared rail for PINS_VC_DIR1..8, plus the nearby visible V1N,
// D24/V2B, and N2P helper chains. The helper D24 inputs are dot-traced to
// local raw and inverted AB/register rails.

module jt054157_page11_vc_dir(
    input  wire       pin_ab2,
    input  wire       pin_ab1,
    input  wire       reg4_d3_buf2,
    input  wire       reg4_d4_buf3,
    input  wire       reg4_d3_buf3,
    input  wire       reg4_d4_buf2,

    input  wire       reg4_d6,
    input  wire       m118a,
    input  wire       pin99,
    input  wire       pin95,
    input  wire       pin112,
    input  wire       reg4_d5,

    output wire       n120a_y,
    output wire       n110b_y,
    output wire       g111a_y,
    output wire       g108b_y,
    output wire       m130a_y,
    output wire       j114a_y,
    output wire       g111b_y,
    output wire       g108a_y,

    output wire       n111b_x,
    output wire       j120a_x,
    output wire       r111a_y,
    output wire       g109a_y,
    output wire       j122a_y,
    output wire       g109b_y,
    output wire       n115b_y,
    output wire       g114a_y,

    output wire       l121a_y,
    output wire       k129_y,
    output wire       l122b_y,
    output wire       l124a_y,
    output wire       l128a_y,
    output wire [7:0] pins_vc_dir);

assign n120a_y = ~pin_ab2; // n120a
assign n110b_y = ~reg4_d3_buf2; // n110b
assign g111a_y = ~pin_ab1; // g111a
assign g108b_y = ~reg4_d4_buf3; // g108b
assign n111b_x = ~((n120a_y & n110b_y) | (g111a_y & reg4_d3_buf2)); // n111b
assign r111a_y = ~n111b_x; // r111a
assign g109a_y = pin_ab1 ? reg4_d4_buf3 : g108b_y; // g116a, g109a
assign n115b_y = reg4_d3_buf2 & g109a_y; // n115b
assign m130a_y = ~pin_ab2; // m130a
assign j114a_y = ~reg4_d3_buf3; // j114a
assign j120a_x = ~((m130a_y & reg4_d3_buf3) | (g111b_y & j114a_y)); // j120a
assign j122a_y = ~j120a_x; // j122a
assign g111b_y = ~pin_ab1; // g111b
assign g108a_y = ~reg4_d4_buf2; // g108a
assign g109b_y = pin_ab1 ? reg4_d4_buf2 : g108a_y; // g115b, g109b
assign g114a_y = reg4_d3_buf3 & g109b_y; // g114a
assign l121a_y = reg4_d6 | m118a; // l121a
assign k129_y = l121a_y; // k129
assign l122b_y = ~pin99; // l122b
assign l124a_y = l122b_y & k129_y; // l124a
assign l128a_y = &{l124a_y,pin95,pin112,reg4_d5}; // l128a
assign pins_vc_dir[0] = ~l128a_y; // a79a
assign pins_vc_dir[1] = ~l128a_y; // a79b
assign pins_vc_dir[2] = ~l128a_y; // a100a
assign pins_vc_dir[3] = ~l128a_y; // a103a
assign pins_vc_dir[4] = ~l128a_y; // a134a
assign pins_vc_dir[5] = ~l128a_y; // c209a
assign pins_vc_dir[6] = ~l128a_y; // c176a
assign pins_vc_dir[7] = ~l128a_y; // c177a
endmodule
